(()=>{'use strict';const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const eur=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);function cards(id,items,fn){$(id).innerHTML=items.map(fn).join('')}function calcCompound(){const p=+$('#compound-start').value||0,m=+$('#compound-monthly').value||0,r=(+$('#compound-rate').value||0)/100/12,n=(+$('#compound-years').value||0)*12;let v=p;for(let i=0;i<n;i++)v=v*(1+r)+m;$('#compound-result').textContent=`Projected value: ${eur(v)}`}function calcFees(){const v=+$('#fee-value').value||0,r=(+$('#fee-rate').value||0)/100,y=+$('#fee-years').value||0;$('#fee-result').textContent=`Simple fee drag: ${eur(v*(1-Math.pow(1-r,y)))}`}function calcDebt(){let b=+$('#debt-balance').value||0,r=(+$('#debt-rate').value||0)/100/12,p=+$('#debt-payment').value||0,months=0,interest=0;if(p<=b*r){$('#debt-result').textContent='Payment is too low to reduce this balance.';return}while(b>0&&months<1200){const i=b*r;interest+=i;b=Math.max(0,b+i-p);months++}$('#debt-result').textContent=`About ${months} months · interest ${eur(interest)}`}function calcBE(){const f=+$('#be-fixed').value||0,p=+$('#be-price').value||0,v=+$('#be-variable').value||0,m=p-v;$('#be-result').textContent=m>0?`${Math.ceil(f/m)} sales per month`:'Price must exceed variable cost.'}function bindCalcs(){[['#compound-start',calcCompound],['#compound-monthly',calcCompound],['#compound-rate',calcCompound],['#compound-years',calcCompound],['#fee-value',calcFees],['#fee-rate',calcFees],['#fee-years',calcFees],['#debt-balance',calcDebt],['#debt-rate',calcDebt],['#debt-payment',calcDebt],['#be-fixed',calcBE],['#be-price',calcBE],['#be-variable',calcBE]].forEach(([s,f])=>$(s).addEventListener('input',f));calcCompound();calcFees();calcDebt();calcBE()}fetch('data/making-money-core.json').then(r=>{if(!r.ok)throw new Error('Wealth guide data unavailable');return r.json()}).then(d=>{cards('#pathway-grid',d.pathways,x=>`<article class="money-card"><span class="status-chip">${esc(x.capital)}</span><h3>${esc(x.title)}</h3><p>${esc(x.focus)}</p><ul>${x.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></article>`);cards('#zero-sprint',d.zeroMoneySprint.weeks,x=>`<article class="money-card"><span class="evidence-chip">${esc(x.week)}</span><h3>${esc(x.title)}</h3><ul>${x.actions.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></article>`);cards('#roadmap-grid',d.roadmap,(x,i)=>`<article class="money-card money-stage"><div class="money-stage-num">${i+1}</div><div><h3>${esc(x.stage)}</h3><p>${esc(x.meaning)}</p><strong>Next action:</strong> ${esc(x.action)}</div></article>`);cards('#flow-grid',d.capitalFlows,x=>`<article class="money-card"><span class="status-chip">${esc(x.status)}</span><h3>${esc(x.sector)}</h3><p><strong>Why capital is moving:</strong> ${esc(x.why)}</p><p><strong>Accessible route:</strong> ${esc(x.accessible)}</p><p><strong>Risks:</strong> ${esc(x.risks)}</p><p><span class="evidence-chip">${esc(x.confidence)}</span> <a href="${esc(x.sourceUrl)}" target="_blank" rel="noopener">${esc(x.source)}</a></p></article>`);cards('#opportunity-grid',d.capitalFlows,x=>`<article class="money-card"><h3>${esc(x.sector)}</h3><p><strong>Evidence:</strong> ${esc(x.confidence)}</p><p><strong>What could work:</strong> ${esc(x.why)}</p><p><strong>What could fail:</strong> ${esc(x.risks)}</p><p><strong>Research route:</strong> ${esc(x.accessible)}</p></article>`);$('#copy-rich-body').innerHTML=d.copyRich.map(x=>`<tr><td>${esc(x.strategy)}</td><td>${esc(x.why)}</td><td>${esc(x.accessible)}</td><td>${esc(x.risk)}</td></tr>`).join('');cards('#structures-grid',d.structures,x=>`<article class="money-card"><h3>${esc(x.name)}</h3><p><strong>Purpose:</strong> ${esc(x.use)}</p><p><strong>When considered:</strong> ${esc(x.when)}</p><p class="money-warning"><strong>Warning:</strong> ${esc(x.warning)}</p></article>`);cards('#france-tax-grid',d.franceTax.items,x=>`<article class="money-card"><span class="evidence-chip">Official source</span><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p><a class="btn alt" href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.source)}</a></article>`);cards('#today-grid',d.quickStartToday,(x,i)=>`<article class="money-card money-stage"><div class="money-stage-num">${i+1}</div><div><h3>${i===0?'Start here':'Next'}</h3><p>${esc(x)}</p></div></article>`);cards('#future-grid',d.futureScenarios,x=>`<article class="money-card future-card"><span class="speculation-label">Scenario · ${esc(x.probability)}</span><h3>${esc(x.theme)}</h3><p>${esc(x.case)}</p><p><strong>Watch:</strong> ${x.watch.map(esc).join(' · ')}</p><p><strong>Failure risk:</strong> ${esc(x.risk)}</p><p class="print-note">Evidence basis: ${esc(x.evidence)}</p></article>`);cards('#downloads-grid',d.downloads,x=>`<article class="money-card money-download"><div><span class="evidence-chip">Free PDF</span><h3>${esc(x.title)}</h3><p>${esc(x.description||'Detailed subject-specific Matrix Reprogrammed guide with evidence checks, worksheets and next actions.')}</p></div><a class="btn" href="downloads/wealth-guides/${esc(x.slug)}.pdf" download>Download PDF</a></article>`);bindCalcs()}).catch(e=>{document.querySelector('main').insertAdjacentHTML('afterbegin',`<section class="section wrap money-warning">${esc(e.message)}</section>`)})})();